  ($pp$windy-hill$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.openspace.org/what-to-do/activities/dogs$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$devils-slide$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.smcgov.org/parks/dogs-san-mateo-county-parks$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$),
  ($pp$junipero-serra$pp$, null, $pp$leash_required$pp$::public.dog_status, $pp$2026-11-07$pp$::date, $pp$https://www.smcgov.org/parks/dogs-san-mateo-county-parks$pp$, $pp$Initial entry, read from the official source on 2026-11-07$pp$)
) as v (slug, previous_status, new_status, changed_on, source_url, note)
join public.places p on p.slug = v.slug
where not exists (
  select 1 from public.place_rule_history h where h.place_id = p.id and h.changed_on = v.changed_on
);

insert into public.sunday_picks (place_id, week_start, note, sort_order)
select p.id, v.week_start, v.note, v.sort_order
from (values
  ($pp$point-isabel$pp$, $pp$2026-11-09$pp$::date, $pp$Off-leash fun by the bay. Bring a leash for the parking lot.$pp$, 0),
  ($pp$fort-funston$pp$, $pp$2026-11-09$pp$::date, $pp$Big sandy bluffs and voice-control zones. Check posted signs.$pp$, 1),
  ($pp$lands-end$pp$, $pp$2026-11-09$pp$::date, $pp$Coastal trail walk. Leashed or voice control per the park.$pp$, 2),
  ($pp$pulgas-ridge$pp$, $pp$2026-11-09$pp$::date, $pp$On-leash trails plus a marked off-leash area.$pp$, 3)
) as v (slug, week_start, note, sort_order)
join public.places p on p.slug = v.slug
on conflict (week_start, place_id) do nothing;
